/* FC AutoList - que el bucle no se duerma cuando la pestana esta de fondo.

   Chrome estrangula los setTimeout de las pestanas ocultas (pasan a ~1 por
   segundo) y tras unos minutos puede congelarlas del todo. Dos contramedidas:
   1) los tiempos los cuenta un Web Worker, que no sufre ese estrangulamiento;
   2) mientras el bucle corre, sonido inaudible en bucle: Chrome no estrangula
      ni congela una pestana que esta reproduciendo audio.
*/
(() => {
  const NS = window.FCAL;

  /* ------------------------------------------------- temporizador en worker */

  const WORKER_CODE = `
    const timers = {};
    onmessage = (e) => {
      const { cmd, id, ms } = e.data;
      if (cmd === 'start') {
        timers[id] = setTimeout(() => { delete timers[id]; postMessage(id); }, ms);
      } else if (cmd === 'cancel') {
        clearTimeout(timers[id]); delete timers[id];
      }
    };`;

  let worker;            // undefined = sin intentar, null = no se pudo crear
  let seq = 0;
  const pending = new Map();

  const getWorker = () => {
    if (worker !== undefined) return worker;
    try {
      const url = URL.createObjectURL(new Blob([WORKER_CODE], { type: 'text/javascript' }));
      worker = new Worker(url);
      worker.onmessage = (e) => {
        const done = pending.get(e.data);
        if (done) { pending.delete(e.data); done(); }
      };
      worker.onerror = () => { worker = null; };
    } catch (err) {
      // la CSP de la pagina puede prohibir workers desde blob:
      worker = null;
      NS.log('Sin temporizador de fondo (' + err.message + '), uso el normal.', 'warn');
    }
    return worker;
  };

  // sustituye al sleep de core.js: mismo contrato, pero cuenta el worker
  NS.sleep = (ms) =>
    new Promise((res) => {
      const w = getWorker();
      if (!w) { setTimeout(res, ms); return; }
      const id = ++seq;
      pending.set(id, res);
      w.postMessage({ cmd: 'start', id, ms });
    });

  NS.timerMode = () => (getWorker() ? 'worker' : 'normal');

  /* ----------------------------------------------------- audio inaudible */

  const SILENCE = 'data:audio/wav;base64,';

  let audio = null;

  NS.keepAwake = (on) => {
    if (!on) {
      if (audio) { audio.pause(); audio.remove(); audio = null; }
      return;
    }
    if (audio) return;
    try {
      audio = document.createElement('audio');
      audio.src = SILENCE;
      audio.loop = true;
      audio.volume = 0.02;
      audio.style.display = 'none';
      document.documentElement.appendChild(audio);
      audio.play().catch((e) => NS.log('El navegador bloqueo el audio de fondo: ' + e.message, 'warn'));
    } catch (e) {
      NS.log('No se pudo activar el modo segundo plano: ' + e.message, 'warn');
    }
  };
})();
